<?php
namespace Tests\Feature;
use App\Models\User; use Illuminate\Foundation\Testing\RefreshDatabase; use Tests\TestCase;
class ResourceCrudTest extends TestCase { use RefreshDatabase; public function test_customer_supplier_and_product_crud_is_available(): void { $user=User::factory()->create(['role'=>'admin']); foreach([['customers',['name'=>'New Customer','email'=>'c@example.com'],\App\Models\Customer::class],['suppliers',['name'=>'New Supplier','email'=>'s@example.com'],\App\Models\Supplier::class],['products',['name'=>'New Service','type'=>'service','unit_price'=>100,'tax_rate'=>18],\App\Models\Product::class]] as [$resource,$data,$class]) { $response=$this->actingAs($user)->post(route($resource.'.store'),$data);$response->assertRedirect(route($resource.'.index'));$record=$class::latest()->first();$this->assertSame($data['name'],$record->name);$this->actingAs($user)->put(route($resource.'.update',$record),array_merge($data,['name'=>'Updated']));$this->assertDatabaseHas($resource,['id'=>$record->id,'name'=>'Updated']);$this->actingAs($user)->delete(route($resource.'.destroy',$record))->assertRedirect();$this->assertSoftDeleted($resource,['id'=>$record->id]); } } }
